package com.nivor.health;
import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.LocalDate;import java.time.LocalDateTime;
public final class HealthDtos{private HealthDtos(){}public record RecordRequest(@NotNull LocalDate date,@DecimalMin("0.01")@Digits(integer=4,fraction=2)BigDecimal weight,@Min(0)@Max(20000)Integer waterMl,@Min(0)@Max(1440)Integer sleepMinutes,@Min(0)@Max(200000)Integer steps,@Min(0)@Max(1440)Integer exerciseMinutes,@Size(max=2000)String notes){}public record RecordView(Long id,LocalDate date,BigDecimal weight,Integer waterMl,Integer sleepMinutes,Integer steps,Integer exerciseMinutes,String notes,LocalDateTime createdAt){static RecordView from(HealthRecord x){return new RecordView(x.getId(),x.getDate(),x.getWeight(),x.getWaterMl(),x.getSleepMinutes(),x.getSteps(),x.getExerciseMinutes(),x.getNotes(),x.getCreatedAt());}}public record Summary(BigDecimal latestWeight,Double averageSleepMinutes,Double averageWaterMl,Double averageSteps,Integer exerciseMinutes,int daysTracked){}}
